
// ═══════════════════════════════════════════════════════════════════════════
// Sendspin "This device" player
// ---------------------------------------------------------------------------
// Turns the browser running the card into a Music Assistant speaker using the
// Sendspin protocol (@sendspin/sendspin-js, bundled at the bottom of this
// file). MA registers it as a player, the MA integration exposes it to HA as a
// media_player, and the card then treats it like any other MA entity.
//
// One shared manager lives on window so the player survives Lovelace
// destroying/recreating cards on view changes, and every card instance on the
// page uses the same connection. Each device opts in separately (stored in
// localStorage), so enabling the feature in the card config does not turn
// every wall tablet or phone into a speaker.
// ═══════════════════════════════════════════════════════════════════════════
const CROW_MEDIA_SS_PREFIX = 'crow_media_ss:';
const CROW_MEDIA_SS_PRODUCT = 'Crow Media Player';
const CROW_MEDIA_SS_ICON = 'M4,6H20V16H4M20,18A2,2 0 0,0 22,16V6C22,4.89 21.1,4 20,4H4C2.89,4 2,4.89 2,6V16A2,2 0 0,0 4,18H0V20H24V18H20Z';


/* ══════════════════════════════════════════════════════════════════════
 * Crow Media Player's integration. When it's installed (it serves this card), each person's data is kept in
 * Home Assistant by it, Home Assistant records what's played on the speakers, the sleep timer and alarms
 * run there, outside services are fetched through it (with the keys kept there) and the AI goes through it.
 * Without it the card works as before.
 * ══════════════════════════════════════════════════════════════════════ */
const CROW_MEDIA_DOMAIN = 'crow_media_player';
const CROW_MEDIA_TMDB = '__crow_media_player__';
const CROW_MEDIA_FETCH_HOSTS = ['itunes.apple.com', 'rss.marketingtools.apple.com', 'rss.applemarketingtools.com', 'api.tvmaze.com',
  'musicbrainz.org', 'coverartarchive.org', 'en.wikipedia.org', 'www.wikidata.org', 'api.themoviedb.org', 'api.discogs.com', 'lrclib.net',
  'api.deezer.com', 'archive.org', 'librivox.org', 'raw.githubusercontent.com', 'api.radio-browser.info'];
const CROW_MEDIA_FETCH_SUFFIXES = ['.radio-browser.info'];
const crowMediaBridge = {
  hass: null, on: null, ready: null, info: null, listeners: new Set(), unsub: null, mixes: null, mixesAt: 0,
  // ask once per connection whether the integration is there
  conn: null,
  detect(hass, conn) {
    if (hass) this.hass = hass;
    if (hass?.connection) this.conn = hass.connection;
    else if (conn && !this.conn) this.conn = conn;
    if (this.ready) return this.ready;
    if (!this.conn) return Promise.resolve(false);
    this.ready = this.conn.sendMessagePromise({ type: CROW_MEDIA_DOMAIN + '/info' })
      .then(info => { this.on = true; this.info = info; this._subscribe(); return true; })
      .catch(() => { this.on = false; return false; });
    return this.ready;
  },
  _subscribe() {
    if (this.unsub || !this.conn) return;
    this.unsub = true;
    this.conn.subscribeMessage(ev => {
      if (ev?.type === 'state') Object.assign(this.info || (this.info = {}), { sleep: ev.sleep, alarms: ev.alarms, keys: ev.keys, resume: ev.resume });
      this.listeners.forEach(fn => { try { fn(ev); } catch (e) { console.warn('[Crow Media Player] update', e); } });
    }, { type: CROW_MEDIA_DOMAIN + '/subscribe' }).then(u => { this.unsub = u; }).catch(() => { this.unsub = null; });
  },
  ws(msg) { return this.conn.sendMessagePromise(msg); },
  hasKey(k) { return !!(this.on && this.info?.keys?.[k]); },
  modules() { return (this.on && this.info?.modules) || {}; },
};
// Home Assistant's frontend user data, or the integration's own store for each person (the same answers)
async function crowMediaUserData(conn, msg) {
  if (await crowMediaBridge.detect(null, conn)) {
    const type = msg.type === 'frontend/get_user_data' ? CROW_MEDIA_DOMAIN + '/data/get' : CROW_MEDIA_DOMAIN + '/data/set';
    return crowMediaBridge.ws({ ...msg, type });
  }
  return conn ? conn.sendMessagePromise(msg) : Promise.resolve(undefined);
}
// The AI and listening-history stores kept in Home Assistant, one saved entry for each store, so a change to
// one (the listening log on every song change) sends only that store rather than all of them together.
// A list of the stores saved this way is kept beside them. The older single entry holding every store
// ('crow_media_ai_local') is read as well, moved across once, and then cleared.
const CROW_MEDIA_AI_PREFIX = 'crow_media_ai_c_', CROW_MEDIA_AI_INDEX = 'crow_media_ai_index', CROW_MEDIA_AI_LEGACY = 'crow_media_ai_local';
let crowMediaAiNames = null, crowMediaAiChain = Promise.resolve();
async function crowMediaAiIndex(conn) {
  if (crowMediaAiNames) return crowMediaAiNames;
  const r = await crowMediaUserData(conn, { type: 'frontend/get_user_data', key: CROW_MEDIA_AI_INDEX }).catch(() => null);
  crowMediaAiNames = new Set(Array.isArray(r?.value) ? r.value.filter(n => typeof n === 'string') : []);
  return crowMediaAiNames;
}
function crowMediaAiPut(conn, name, store) {
  const run = async () => {
    if (!conn || !name) return;
    const names = await crowMediaAiIndex(conn);
    await crowMediaUserData(conn, { type: 'frontend/set_user_data', key: CROW_MEDIA_AI_PREFIX + name, value: store ?? {} });
    if (!names.has(name)) {
      names.add(name);
      await crowMediaUserData(conn, { type: 'frontend/set_user_data', key: CROW_MEDIA_AI_INDEX, value: [...names] });
    }
  };
  crowMediaAiChain = crowMediaAiChain.then(run, run).catch(() => {});
  return crowMediaAiChain;
}
// every store as { name: store }, with anything still in the older single entry moved across
async function crowMediaAiGetAll(conn) {
  if (!conn) return {};
  const names = await crowMediaAiIndex(conn);
  const legacyRes = await crowMediaUserData(conn, { type: 'frontend/get_user_data', key: CROW_MEDIA_AI_LEGACY }).catch(() => null);
  const legacy = legacyRes?.value && typeof legacyRes.value === 'object' ? legacyRes.value : null;
  const out = {};
  const got = await Promise.all([...names].map(n => crowMediaUserData(conn, { type: 'frontend/get_user_data', key: CROW_MEDIA_AI_PREFIX + n })
    .then(r => [n, r?.value]).catch(() => [n, undefined])));
  got.forEach(([n, v]) => { if (v && typeof v === 'object') out[n] = v; });
  if (legacy) {
    const moves = [];
    Object.entries(legacy).forEach(([n, v]) => {
      if (!v || typeof v !== 'object') return;
      out[n] = { ...v, ...(out[n] || {}) };   // the newer copy wins
      moves.push(crowMediaAiPut(conn, n, out[n]));
    });
    await Promise.all(moves);
    await crowMediaUserData(conn, { type: 'frontend/set_user_data', key: CROW_MEDIA_AI_LEGACY, value: null }).catch(() => {});
  }
  return out;
}
// Your own small lists, kept in Home Assistant so they follow you between devices: recent library searches,
// announcement history and the songs the AI has already added for each song. One saved entry holds them all
// ('crow_media_personal'; in the integration's store for each person, or Home Assistant's own user data
// without it), and each device keeps its own copy for instant reading. The first time a device
// connects, what it has is added to what's in Home Assistant; after that Home Assistant's copy is the one used,
// so something removed on one device stays removed on the others.
const CROW_MEDIA_PERSONAL = 'crow_media_personal', CROW_MEDIA_PERSONAL_SYNCED = 'crow_media_personal_synced';
const CROW_MEDIA_PERSONAL_KEYS = ['crow_media_ma_recent_searches', 'crow_media_announce_history', 'crow_media_ai_similar_added',
  'crow_media_ai_same_year_added', 'crow_media_ai_same_genre_added', 'crow_media_ai_same_genre_year_added'];
let crowMediaPersonalT = 0;
function crowMediaPersonalRead(k) { try { const v = JSON.parse(localStorage.getItem(k) || 'null'); return v ?? null; } catch (_) { return null; } }
// saved two seconds after the last change, so a burst of changes is one save
function crowMediaPersonalSave(conn) {
  if (!conn) return;
  clearTimeout(crowMediaPersonalT);
  crowMediaPersonalT = setTimeout(() => {
    const value = {};
    CROW_MEDIA_PERSONAL_KEYS.forEach(k => { value[k] = crowMediaPersonalRead(k); });
    crowMediaUserData(conn, { type: 'frontend/set_user_data', key: CROW_MEDIA_PERSONAL, value }).catch(() => {});
  }, 2000);
}
// this device's lists and Home Assistant's together (the first time a device connects)
function crowMediaPersonalMerge(k, mine, theirs) {
  if (mine == null) return theirs;
  if (theirs == null) return mine;
  if (k === 'crow_media_ma_recent_searches' && Array.isArray(mine) && Array.isArray(theirs)) {
    const by = new Map();
    [...theirs, ...mine].forEach(e => { if (!e) return; const id = (e.tab || '') + '|' + String(e.query || '').toLowerCase(); const o = by.get(id); if (!o || (e.ts || 0) > (o.ts || 0)) by.set(id, e); });
    return [...by.values()].sort((a, b) => (b.ts || 0) - (a.ts || 0)).slice(0, 50);
  }
  if (k === 'crow_media_announce_history' && Array.isArray(mine) && Array.isArray(theirs)) {
    const by = new Map();
    [...theirs, ...mine].forEach(e => { if (!e?.text) return; const id = e.text.toLowerCase(); const o = by.get(id); if (!o) by.set(id, { ...e }); else { if ((e.ts || 0) > (o.ts || 0)) Object.assign(o, e, { favourite: o.favourite || e.favourite }); else o.favourite = o.favourite || e.favourite; } });
    const all = [...by.values()].sort((a, b) => (b.ts || 0) - (a.ts || 0));
    return [...all.filter(h => h.favourite), ...all.filter(h => !h.favourite).slice(0, 10)];
  }
  if (typeof mine === 'object' && typeof theirs === 'object' && !Array.isArray(mine) && !Array.isArray(theirs)) {
    const out = { ...theirs };
    Object.entries(mine).forEach(([key, v]) => { out[key] = Array.isArray(v) && Array.isArray(out[key]) ? [...new Set([...out[key], ...v])] : (out[key] ?? v); });
    return out;
  }
  return theirs;
}
async function crowMediaPersonalLoad(conn) {
  if (!conn) return;
  const res = await crowMediaUserData(conn, { type: 'frontend/get_user_data', key: CROW_MEDIA_PERSONAL }).catch(() => null);
  const theirs = res?.value && typeof res.value === 'object' ? res.value : null;
  let first = false;
  try { first = !localStorage.getItem(CROW_MEDIA_PERSONAL_SYNCED); } catch (_) {}
  let upload = !theirs;
  CROW_MEDIA_PERSONAL_KEYS.forEach(k => {
    const mine = crowMediaPersonalRead(k), there = theirs ? (theirs[k] ?? null) : null;
    const v = first || !theirs ? crowMediaPersonalMerge(k, mine, there) : there;
    if (JSON.stringify(v) !== JSON.stringify(there)) upload = true;
    try { v == null ? localStorage.removeItem(k) : localStorage.setItem(k, JSON.stringify(v)); } catch (_) {}
  });
  try { localStorage.setItem(CROW_MEDIA_PERSONAL_SYNCED, '1'); } catch (_) {}
  if (upload) crowMediaPersonalSave(conn);
}
async function crowMediaAiClear(conn) {
  if (!conn) return;
  const names = await crowMediaAiIndex(conn).catch(() => new Set());
  await Promise.all([...names].map(n => crowMediaUserData(conn, { type: 'frontend/set_user_data', key: CROW_MEDIA_AI_PREFIX + n, value: null }).catch(() => {})));
  await Promise.all([CROW_MEDIA_AI_INDEX, CROW_MEDIA_AI_LEGACY].map(k => crowMediaUserData(conn, { type: 'frontend/set_user_data', key: k, value: null }).catch(() => {})));
  crowMediaAiNames = new Set();
}
// Outside services through Home Assistant (no relays, keys kept there); anything else as before
function crowMediaFetchable(url) {
  try {
    const u = new URL(String(url), location.href);
    if (u.origin === location.origin) return false;
    const h = u.hostname.toLowerCase();
    return CROW_MEDIA_FETCH_HOSTS.includes(h) || CROW_MEDIA_FETCH_SUFFIXES.some(x => h.endsWith(x));
  } catch (_) { return false; }
}
// crowDirect: true asks the site straight from this device (a big file such as the 20 MB TV guide, which
// Home Assistant won't pass on). When Home Assistant can't fetch something for the card (too big, or it was
// sent somewhere the integration doesn't allow), this device asks the site itself instead.
async function crowFetch(url, opts) {
  const b = crowMediaBridge;
  const direct = !!opts?.crowDirect;
  if (opts && 'crowDirect' in opts) { opts = { ...opts }; delete opts.crowDirect; }
  const method = String(opts?.method || 'GET').toUpperCase();
  if (!direct && b.on && b.hass?.fetchWithAuth && method === 'GET' && typeof url === 'string' && crowMediaFetchable(url)) {
    const o = { ...(opts || {}) };
    delete o.headers; delete o.mode; delete o.credentials;
    const r = await b.hass.fetchWithAuth('/api/' + CROW_MEDIA_DOMAIN + '/fetch?url=' + encodeURIComponent(url), o);
    if (r.status === 413) return window.fetch(url, opts);
    // Home Assistant couldn't get an answer (the site was down, overloaded or out of its reach): this device
    // asks the site itself once. Its answer is only used when it's a real one; otherwise Home Assistant's
    // error is passed on as it was. (Sites that need a key kept on the server just refuse, so nothing changes.)
    if (r.status === 502 || r.status === 503 || r.status === 504) {
      try {
        const d = await window.fetch(url, opts);
        if (d.ok || d.status === 404) return d;
      } catch (e) { if (e?.name === 'AbortError') throw e; }
      return r;
    }
    if (r.status === 403) {
      let t = '';
      try { t = await r.clone().text(); } catch (_) { t = ''; }
      if (/^(Not a site|Redirected somewhere) Crow Media Player/.test(t)) return window.fetch(url, opts);
    }
    return r;
  }
  return window.fetch(url, opts);
}
// the public relays are only for when Home Assistant can't fetch for the card
function crowMediaRelays() { return crowMediaBridge.on ? [] : CROW_MEDIA_RELAYS; }
// the files the card loads when a feature is first used
const CROW_MEDIA_BASE = (() => { try { return new URL('.', document.currentScript.src).href; } catch (_) { return '/' + CROW_MEDIA_DOMAIN + '/'; } })();
const CROW_MEDIA_FILES = { editor: 'crow-media-editor.js', fullscreen: 'crow-media-fullscreen.js', pdf: 'crow-media-pdf.js', saver: 'crow-media-screensaver.js', viz: 'crow-media-visualiser.js',
  video: 'crow-media-video.js', panels: 'crow-media-panels.js', library: 'crow-media-library.js', sendspin: 'crow-media-sendspin.js' };
function crowMediaLoad(mod) {
  const loads = window.__crowMediaLoads || (window.__crowMediaLoads = {});
  if (window.CrowMediaKit?.ready?.[mod]) return Promise.resolve();
  if (!loads[mod]) {
    loads[mod] = new Promise((resolve, reject) => {
      const src = crowMediaBridge.modules()[mod] || (CROW_MEDIA_BASE + CROW_MEDIA_FILES[mod] + '?v=' + CROW_MEDIA_VERSION);
      const el = document.createElement('script');
      el.src = src;
      el.onload = () => (window.CrowMediaKit?.ready?.[mod] ? resolve() : reject(new Error('Crow Media Player: ' + mod + ' didn’t load')));
      el.onerror = () => { delete loads[mod]; reject(new Error('Crow Media Player couldn’t load ' + CROW_MEDIA_FILES[mod] + '. Check the connection and try again.')); };
      document.head.appendChild(el);
    });
  }
  return loads[mod];
}


