// menus the card puts on the page go above it while it's full screen (the browser's top layer)
function crowMediaFsGlobalCss() {
  if (document.getElementById('crowMediaFsGlobal')) return;
  const st = document.createElement('style');
  st.id = 'crowMediaFsGlobal';
  st.textContent = '[data-crow-fs-pop]:popover-open{inset:auto;margin:0;border:0;padding:0;overflow:visible;background-color:transparent;color:inherit;width:auto;height:auto;max-width:none;max-height:none;}';
  document.head.appendChild(st);
}

function crowMediaIsCompanionApp() {
  try {
    if (/Home ?Assistant\//i.test(navigator.userAgent || '')) return true;
    if (window.externalApp) return true;                                   // Android app bridge
    if (window.webkit?.messageHandlers?.getExternalAuth) return true;      // iPhone / iPad / Mac app bridge
  } catch (_) {}
  return false;
}

function crowMediaSendspin() {
  if (!window.__crowMediaSendspin) window.__crowMediaSendspin = new CrowMediaSendspinManager();
  return window.__crowMediaSendspin;
}







/* ══════════════════════════════════════════════════════════════════
 * SCREENSAVER: analogue clock dials (twelve faces, smooth sweeping
 * second hand), drawn on a canvas.
 * ══════════════════════════════════════════════════════════════════ */
// Canvas roundRect for browsers without it (only added when missing)
// ── Canvas roundRect polyfill ─────────────────────────────────────
(function () {
  const proto = CanvasRenderingContext2D.prototype;
  if (!proto.roundRect) {
    proto.roundRect = function (x, y, w, h, r) {
      r = Math.min(Math.abs(r || 0), Math.abs(w / 2), Math.abs(h / 2));
      this.beginPath();
      this.moveTo(x + r, y);
      this.lineTo(x + w - r, y);
      this.arcTo(x + w, y, x + w, y + r, r);
      this.lineTo(x + w, y + h - r);
      this.arcTo(x + w, y + h, x + w - r, y + h, r);
      this.lineTo(x + r, y + h);
      this.arcTo(x, y + h, x, y + h - r, r);
      this.lineTo(x, y + r);
      this.arcTo(x, y, x + r, y, r);
      this.closePath();
      return this;
    };
  }
}());



