                    if (!this._confirmedArtUrls) this._confirmedArtUrls = new Map();
                    this._confirmedArtUrls.set(effectiveUrl, confirmed);
                    mainImg.onerror = null;
                    mainImg.onload  = () => { mainImg.onload = null; mainImg.classList.remove('hidden'); mainPh.classList.add('hidden'); this._extractAmbientColor(mainImg); };
